namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>().HasData(
            new Shipment { Id = 1, TrackingNumber = "SHP-001", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = "Delivered", RecipientName = "Alice Johnson", ShippedDate = new DateTime(2025, 1, 10, 0, 0, 0, DateTimeKind.Utc), EstimatedDelivery = new DateTime(2025, 1, 15, 0, 0, 0, DateTimeKind.Utc), ActualDelivery = new DateTime(2025, 1, 14, 0, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 2, TrackingNumber = "SHP-002", Origin = "Chicago, IL", Destination = "Houston, TX", Status = "In Transit", RecipientName = "Bob Smith", ShippedDate = new DateTime(2025, 1, 18, 0, 0, 0, DateTimeKind.Utc), EstimatedDelivery = new DateTime(2025, 1, 23, 0, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 3, TrackingNumber = "SHP-003", Origin = "Seattle, WA", Destination = "Denver, CO", Status = "Pending", RecipientName = "Carol Davis", ShippedDate = new DateTime(2025, 1, 20, 0, 0, 0, DateTimeKind.Utc), EstimatedDelivery = new DateTime(2025, 1, 26, 0, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 4, TrackingNumber = "SHP-004", Origin = "Miami, FL", Destination = "Atlanta, GA", Status = "Delayed", RecipientName = "Dan Wilson", ShippedDate = new DateTime(2025, 1, 12, 0, 0, 0, DateTimeKind.Utc), EstimatedDelivery = new DateTime(2025, 1, 17, 0, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 5, TrackingNumber = "SHP-005", Origin = "Boston, MA", Destination = "Phoenix, AZ", Status = "In Transit", RecipientName = "Eve Martinez", ShippedDate = new DateTime(2025, 1, 19, 0, 0, 0, DateTimeKind.Utc), EstimatedDelivery = new DateTime(2025, 1, 25, 0, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 6, TrackingNumber = "SHP-006", Origin = "San Francisco, CA", Destination = "Portland, OR", Status = "Pending", RecipientName = "Frank Lee", ShippedDate = new DateTime(2025, 1, 21, 0, 0, 0, DateTimeKind.Utc), EstimatedDelivery = new DateTime(2025, 1, 24, 0, 0, 0, DateTimeKind.Utc) }
        );
    }
}

