@page "/shipments"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Shipments</PageTitle>

<h1>Shipments</h1>

<div class="mb-3">
    <label class="form-label">Filter by Status:</label>
    <select class="form-select w-auto d-inline-block" @onchange="OnStatusFilterChanged">
        <option value="">All</option>
        <option value="Pending">Pending</option>
        <option value="In Transit">In Transit</option>
        <option value="Delivered">Delivered</option>
        <option value="Delayed">Delayed</option>
    </select>
</div>

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments is not null)
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking Number</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Estimated Delivery</th>
                <th>Update Status</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in shipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery.ToShortDateString()</td>
                    <td>
                        <select class="form-select form-select-sm" value="@shipment.Status"
                                @onchange="e => OnStatusChanged(shipment.Id, e)">
                            <option value="Pending">Pending</option>
                            <option value="In Transit">In Transit</option>
                            <option value="Delivered">Delivered</option>
                            <option value="Delayed">Delayed</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private bool loading = true;
    private string? currentFilter;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetShipmentsAsync(currentFilter);
        loading = false;
    }

    private async Task OnStatusFilterChanged(ChangeEventArgs e)
    {
        currentFilter = e.Value?.ToString();
        if (string.IsNullOrEmpty(currentFilter))
            currentFilter = null;
        await LoadShipments();
    }

    private async Task OnStatusChanged(int id, ChangeEventArgs e)
    {
        var newStatus = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newStatus))
        {
            await ShipmentService.UpdateStatusAsync(id, newStatus);
            await LoadShipments();
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Pending" => "bg-warning text-dark",
        "Delayed" => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track a Shipment</h1>

<div class="mb-3 d-flex gap-2">
    <input type="text" class="form-control w-auto" placeholder="Enter tracking number"
           @bind="trackingNumber" @bind:event="oninput" />
    <button class="btn btn-primary" @onclick="Search" disabled="@searching">Search</button>
</div>

@if (searching)
{
    <p><em>Searching...</em></p>
}
else if (searched && shipment is null)
{
    <div class="alert alert-warning">Shipment not found.</div>
}
else if (shipment is not null)
{
    <div class="card" style="max-width: 500px;">
        <div class="card-body">
            <h5 class="card-title">@shipment.TrackingNumber</h5>
            <p><strong>Origin:</strong> @shipment.Origin</p>
            <p><strong>Destination:</strong> @shipment.Destination</p>
            <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></p>
            <p><strong>Shipped Date:</strong> @shipment.ShippedDate.ToShortDateString()</p>
            <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToShortDateString()</p>
            @if (shipment.ActualDelivery.HasValue)
            {
                <p><strong>Actual Delivery:</strong> @shipment.ActualDelivery.Value.ToShortDateString()</p>
            }
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool searching;
    private bool searched;

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        searching = true;
        searched = false;
        shipment = null;

        shipment = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());

        searched = true;
        searching = false;
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Pending" => "bg-warning text-dark",
        "Delayed" => "bg-danger",
        _ => "bg-secondary"
    };
}

